 if(action==='move-item'){const result=await api.move(data.from,data.to,data.updateLinks);const map=p=>p===data.from?data.to:p.startsWith(data.from+'/')?data.to+p.slice(data.from.length):p;
  for(const tab of tabs){const next=map(tab.path);tab.path=next;const change=result.changes.find(c=>c.path===next);if(change){const transaction={changes:change.edits,annotations:Transaction.addToHistory.of(false)};if(tab===current&&editor)editor.dispatch(transaction);else tab.state=tab.state.update(transaction).state;}const disk=await api.read(next);if(tab.state.doc.toString()!==disk.text){const selection=tab.state.selection.main;const transaction={changes:minimalChange(tab.state.doc.toString(),disk.text),annotations:Transaction.addToHistory.of(false)};if(tab===current&&editor)editor.dispatch(transaction);else tab.state=tab.state.update(transaction).state;}tab.text=disk.text;tab.version=disk.version;tab.saveError=null;clearTimeout(tab.autosaveTimer);}
  panes.relocate(map);const l=layout.snapshot();layout.restore({...l,collapsedFolders:l.collapsedFolders.map(map)});if(preferences.newNoteFolder)preferences.newNoteFolder=map(preferences.newNoteFolder);if(attachmentConfig.mode==='folder'&&attachmentConfig.folder)attachmentConfig.folder=map(attachmentConfig.folder);ai.relocate?.(map);status(`Moved · ${result.updatedLinks} links updated${result.warnings?.length?' · '+result.warnings.join(' '):''}`);
 }
